import * as tf from '@tensorflow/tfjs'
import * as facemesh from '@tensorflow-models/facemesh';
import { ScatterGL } from 'scatter-gl';
import { getImgFromURL } from '../../../../../lib';
import {
  drawPath, isMobile, TRIANGULATION,
  setupCamera,
} from './Util';

// reference
// https://github.com/hpssjellis/beginner-tensorflowjs-examples-in-javascript/tree/master/tfjs-models/facemesh
// https://github.com/hpssjellis/beginner-tensorflowjs-examples-in-javascript/tree/master/tfjs-models
// https://github.com/hpssjellis/Face-Detection
// https://github.com/nicknochnack?tab=repositories&q=tensorflow&type=&language=&sort=
// https://github.com/nicknochnack/FacialLandmarkDetection
// https://www.rocksetta.com/
// https://www.youtube.com/watch?v=7lXYGDVHUNw

let index = 0;

let divColor: HTMLElement[] = [];

export class NFaceCam {
  host: HTMLElement;
  mobile: boolean = false;
  VIDEO_SIZE = 400;

  imgSmaile: HTMLImageElement;
  imgHairband: HTMLImageElement;
  imgSunglass: HTMLImageElement;

  renderMode: number = 0;
  constructor(id: string) {
    this.mobile = isMobile();
    this.host = document.getElementById(id) as HTMLElement;

    let row0 = document.createElement('div');
    row0.style.display = 'flex';
    this.host.append(row0);

    const video = document.createElement('video');
    row0.append(video); // for debugging
    video.id = 'video';
    // video.style.transform = 'scaleX(-1)';

    const canvasOut = document.createElement('canvas');
    row0.append(canvasOut);
    canvasOut.width = this.VIDEO_SIZE;
    canvasOut.height = this.VIDEO_SIZE;
    canvasOut.id = 'canvas-out';
    const ctxOut = canvasOut.getContext('2d') as CanvasRenderingContext2D;


    let row1 = document.createElement('div');
    row1.style.display = 'flex';
    this.host.append(row1);

    const canvas = document.createElement('canvas');
    row1.append(canvas);
    const ctx = canvas.getContext('2d') as CanvasRenderingContext2D;

    const divGL = document.createElement('div');
    divGL.style.width = this.VIDEO_SIZE + 'px';
    divGL.style.height = this.VIDEO_SIZE + 'px';
    row1.append(divGL);

    getImgFromURL('https://raw.githubusercontent.com/NamjuLee/data/master/img/smile.png').then((img: HTMLImageElement | void) => {
      if (!img) return;
      // console.log(img)
      this.imgSmaile = img;

      getImgFromURL('https://raw.githubusercontent.com/NamjuLee/data/master/img/hair%20band.png').then((img: HTMLImageElement | void) => {
        if (!img) return;
        // console.log(img)
        this.imgHairband = img;

  
        getImgFromURL('https://raw.githubusercontent.com/NamjuLee/data/master/img/sunglass.png').then((img: HTMLImageElement | void) => {
          if (!img) return;
          // console.log(img)
          this.imgSunglass = img;
          this.init(divGL, ctx, ctxOut, video);
    
        });

      });
    });

    this.initUI();
  }
  async init(divGL: HTMLDivElement, ctx: CanvasRenderingContext2D, ctxOut: CanvasRenderingContext2D, video: HTMLVideoElement) {
    await mainInit(divGL, ctx, ctxOut, video, this.mobile, this.VIDEO_SIZE, this.imgSmaile, this.imgHairband, this.imgSunglass, this.renderMode);
  }
  public initUI() {
    let slider = document.createElement('input');
    slider.type = 'range';
    slider.min = '0';
    slider.max = '467';
    slider.step = '1';
    slider.value = '0';
    slider.style.width = '300px';
    slider.oninput = () => {
      // console.log(slider.value);
      index = +slider.value;
      indexText.textContent = slider.value;
    };
    this.host.append(slider);

    let slider2 = document.createElement('input');
    slider2.type = 'range';
    slider2.min = '0';
    slider2.max = '5';
    slider2.step = '1';
    slider2.value = '2';
    slider2.style.width = '300px';
    slider2.oninput = () => {
      // console.log(slider2.value);
      RENDER_TYPE = +slider2.value;
    };
    this.host.append(slider2);

    let indexText = document.createElement('div');
    indexText.textContent = '0';
    this.host.append(indexText);

    let div0 = document.createElement('div');
    div0.style.width = '50px';
    div0.style.height = '50px';
    div0.style.background = '#000000';
    this.host.append(div0);
    divColor.push(div0);

    div0 = document.createElement('div');
    div0.style.width = '50px';
    div0.style.height = '50px';
    div0.style.background = '#000000';
    this.host.append(div0);
    divColor.push(div0);

    div0 = document.createElement('div');
    div0.style.width = '50px';
    div0.style.height = '50px';
    div0.style.background = '#000000';
    this.host.append(div0);
    divColor.push(div0);
  }
}

let isTriangulateMesh = false;
let renderPointcloud = true;
let scatterGLHasInitialized = false;
let pos: number[][] = [[0, 0], [0, 0], [0, 0]];

const mainInit = async (hostDiv: HTMLElement, ctx: CanvasRenderingContext2D, ctxOut: CanvasRenderingContext2D, video: HTMLVideoElement, isMobile: boolean, VIDEO_SIZE: number, img: HTMLImageElement,imgHairBand: HTMLImageElement, imgSunglass: HTMLImageElement, renderMode = 0) => {
  console.log(tf.setBackend);
  await tf.setBackend('webgl'); // ['wasm', 'webgl', 'cpu']
  // setupDatGui();
  let scatterGL: ScatterGL = undefined;

  if (renderPointcloud) {
    //   document.querySelector('#scatter-gl-container').style =
    //       `width: ${VIDEO_SIZE}px; height: ${VIDEO_SIZE}px;`;
//     console.log(hostDiv)
    scatterGL = new ScatterGL(hostDiv, { 'rotateOnStart': false, 'selectEnabled': false });

    // scatterGL.si
  }
  // stats.showPanel(0);  // 0: fps, 1: ms, 2: mb, 3+: custom
  // document.getElementById('main').appendChild(stats.dom);

  console.log();
  await setupCamera(video, isMobile, VIDEO_SIZE);
  video.play();
  // videoWidth = video.videoWidth;
  // videoHeight = video.videoHeight;
  video.width = video.videoWidth;
  video.height = video.videoHeight;

  ctx.canvas.width = video.videoWidth;
  ctx.canvas.height = video.videoHeight;
  // const canvasContainer = document.querySelector('.canvas-wrapper');
  ctx.canvas.style.width = video.videoWidth + 'px';
  ctx.canvas.style.height = video.videoHeight + 'px';
  // canvasContainer.style = `width: ${videoWidth}px; height: ${videoHeight}px`;

  // ctx = ctx.canvas.getContext('2d') as CanvasRenderingContext2D;
  // ctx.translate(ctx.canvas.width, 0);
  // ctx.scale(-1, 1);
  ctx.fillStyle = '#32EEDB';
  ctx.strokeStyle = 'rgba(0, 200, 200, 0.35)';
  ctx.lineWidth = 0.5;
  // ctx.globalCompositeOperation = 'screen';

  const model = await facemesh.load({ maxFaces: 200 });
  console.log(model)
  renderPrediction(model, ctx, ctxOut, video, scatterGL, img, imgHairBand, imgSunglass, renderMode);
};
let RENDER_TYPE = 2

const renderPrediction = async (model: any, ctx: CanvasRenderingContext2D, ctxOut: CanvasRenderingContext2D, video: HTMLVideoElement, scatterGL: ScatterGL | undefined, img: HTMLImageElement, imgHairBand: HTMLImageElement, imgSunglass: HTMLImageElement, renderMode: number = 0) => {
  // ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);
  // ctx.beginPath();
  // ctx.arc(10, 10, 100, 0, 3.14 * 2);
  // ctx.fill();
  // stats.begin();

  const predictions = await model.estimateFaces(video);
  if (predictions[0]) {
    // console.log(predictions[0].faceInViewConfidence)
    ctx.drawImage(video, 0, 0, video.videoWidth, video.videoHeight, 0, 0, ctx.canvas.width, ctx.canvas.height);
    ctxOut.drawImage(video, 0, 0, video.videoWidth, video.videoHeight, 0, 0, ctx.canvas.width, ctx.canvas.height);



    // ctxOut.beginPath();
    // ctxOut.arc(0, 0, 300, 0, Math.PI * 2);
    // ctxOut.closePath();
    // ctxOut.fill();
    // ctx.drawImage(video, 0, 0, videoWidth, videoHeight, 0, 0, canvas.width, canvas.height);

    // document.getElementById('myDiv01').innerHTML = '' 
    if (predictions.length > 0) {


      // ..............................................................................

      predictions.forEach((prediction: any) => {
        try {
          // document.getElementById('myDiv01').innerHTML += 'Confidence: ' + prediction.faceInViewConfidence.toFixed(4) + '<br>'
          // console.log(prediction.faceInViewConfidence.toFixed(4))
        } catch (err) {
          // document.getElementById('myDiv01').innerHTML = err.message;
        }

        const keypoints = prediction.scaledMesh;

        const indexFiltered = [50, 280, 8];
        for (let i = 0; i < indexFiltered.length; ++i) {
          const x = keypoints[indexFiltered[i]][0];
          const y = keypoints[indexFiltered[i]][1];

          const col = ctx.getImageData(x, y, 1, 1);
          // console.log(col.data[0], col.data[1], col.data[2], col.data[3]);
          divColor[i].style.background = `rgba(${col.data[0]}, ${col.data[1]}, ${col.data[2]}, ${col.data[3]})`;
        }
        const col = ctx.getImageData(0, 0, 1, 1);
    //     console.log('white', col.data[0], col.data[1], col.data[2]);

        ctx.beginPath();
        ctx.arc(0, 0, 30, 0, 3.14 * 2)
        ctx.stroke();

        // console.log(keypoints[0][2])
        if (isTriangulateMesh) {
          for (let i = 0; i < TRIANGULATION.length / 3; i++) {
            const points = [TRIANGULATION[i * 3], TRIANGULATION[i * 3 + 1], TRIANGULATION[i * 3 + 2]].map(index => keypoints[index]);

            //  https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/globalCompositeOperation
            ctx.globalCompositeOperation = 'screen';
            drawPath(ctx, points, true);
            ctx.globalCompositeOperation = 'source-over';
          }
        } else {
          for (let i = 0; i < keypoints.length; i++) {
            const x = keypoints[i][0];
            const y = keypoints[i][1];

            ctx.beginPath();
            ctx.arc(x, y, 1 /* radius */, 0, 2 * Math.PI);
            ctx.fill();

            ctx.strokeStyle = '#000000';
            ctx.font = `12px Arial`;
            ctx.strokeText(`${i}`, x - 10, y - 2);
          }
      //     console.log('length:', keypoints.length);


          const indexFiltered = [50, 280, 8];
          ctx.fillStyle = '#ff0000';
          for (let i = 0; i < indexFiltered.length; ++i) {
            const x = keypoints[indexFiltered[i]][0];
            const y = keypoints[indexFiltered[i]][1];
            ctx.beginPath();
            ctx.arc(x, y, 4 /* radius */, 0, 2 * Math.PI);
            ctx.fill();

            pos[i][0] = x;
            pos[i][1] = y;
          }


          const x = keypoints[index][0];
          const y = keypoints[index][1];
          ctx.beginPath();
          ctx.arc(x, y, 4 /* radius */, 0, 2 * Math.PI);
          ctx.fill();

          ctx.fillStyle = '#32EEDB';
        }



        //. .............................


        // 159   386
        // Le    Re
        // 145    374
        //    13
        //   Mouth
        //    14

        ctxOut.fillStyle = '#ff0000';
        const lex = keypoints[159][0];
        const ley = keypoints[145][1] + (keypoints[159][1] - keypoints[145][1]) * 0.5;

        if (RENDER_TYPE === 0) {
          ctxOut.beginPath();
          ctxOut.arc(lex, ley, 10, 0, 2 * Math.PI);
          ctxOut.fill();
        }

        const rex = keypoints[386][0];
        const rey = keypoints[374][1] + (keypoints[386][1] - keypoints[374][1]) * 0.5;
        if (RENDER_TYPE === 0) {
          ctxOut.beginPath();
          ctxOut.arc(rex, rey, 10, 0, 2 * Math.PI);
          ctxOut.fill();
        }

        const mx = keypoints[13][0];
        const my = keypoints[13][1] + (keypoints[14][1] - keypoints[13][1]) * 0.5;
        if (RENDER_TYPE === 0) {
          ctxOut.beginPath();
          ctxOut.arc(mx, my, 10, 0, 2 * Math.PI);
          ctxOut.fill();
        }



        const angle = getAngleBetween(lex, ley, rex, rey)

        ctxOut.save();
        ctxOut.translate(mx, my - (my - rey) * 0.6);
        // ctxOut.translate(mx, my - (my - rey ));
        ctxOut.rotate(-angle - Math.PI * 0.5);
        ctxOut.scale((rex - lex) / 130, (ley - my) / 130)

        if (img !== undefined) {
          if (RENDER_TYPE === 1) {
            ctxOut.drawImage(img, -150, -150);
          } else if (RENDER_TYPE === 2) {
            ctxOut.drawImage(imgHairBand, -imgHairBand.width * 0.5, -250);
          } else if (RENDER_TYPE === 3) {
            ctxOut.drawImage(imgSunglass, -imgSunglass.width * 0.5, -263);
          } else if (RENDER_TYPE === 4) {
            // ctxOut.drawImage(img, -150, -150);
            ctxOut.globalCompositeOperation = 'xor';
            // ctxOut.beginPath();
            
            // const imgData = ctxOut.getImageData(-150, -150, 150, 150);
            
            ctxOut.filter = `blur(${10}px)`;
            // ctxOut.drawImage(img, -150, -150);

            // ctxOut.putImageData(imgData, -150, -150)
            ctxOut.ellipse(0, 0, 150, 150, 0, 0, 2 * Math.PI);
            ctxOut.fillStyle = '#fff';
            // // ctxOut.drawImage(ctx.canvas, 0,0, 150, 150);
            // // ctxOut.fillStyle = `rgba(${this.rgb[0]}, ${this.rgb[1]}, ${this.rgb[2]}, ${this.opacity})`;
            ctxOut.fill();
            // ctxOut.clip()

            // ctxOut.restore();

            // const ctxNew = document.createElement('canvas').getContext('2d');
            // ctxNew.drawImage(ctxOut.canvas, 0, 0);
            // ctxNew.filter = `blur(${10}px)`;

   
            // ctxOut.drawImage(ctxNew.canvas, 0, 0);
    
            ctxOut.filter = "none";
            ctxOut.globalCompositeOperation = 'source-over'
          }
        }


        ctxOut.lineWidth = 2;
        ctxOut.strokeStyle = '#0f0';
        ctxOut.beginPath();
        ctxOut.rect(-150, -150, 300, 300);
        ctxOut.closePath();
        if (RENDER_TYPE === 0) {
          ctxOut.stroke();
        }

        ctxOut.beginPath();
        ctxOut.arc(0, 0, 100, 0, 2 * Math.PI);
        if (RENDER_TYPE === 0) {
          ctxOut.stroke();
        }

        ctxOut.restore();
        // }

        // if (isTriangulateMesh) {
        for (let i = 0; i < TRIANGULATION.length / 3; i++) {
          const points = [TRIANGULATION[i * 3], TRIANGULATION[i * 3 + 1], TRIANGULATION[i * 3 + 2]].map(index => keypoints[index]);

          const indexFiltered = [50, 280, 8];
          ctx.fillStyle = '#ff0000';
          for (let i = 0; i < indexFiltered.length; ++i) {
            const x = keypoints[indexFiltered[i]][0];
            const y = keypoints[indexFiltered[i]][1];
            ctxOut.beginPath();
            ctxOut.arc(x, y, 4 /* radius */, 0, 2 * Math.PI);
            // ctxOut.fill();

            // pos[i][0] = x;
            // pos[i][1] = y;
          }
        }
        // }



      });

      // ..............................................................................

      if (renderPointcloud && renderPointcloud && scatterGL !== undefined) {

        const pointsData = predictions.map((prediction: any) => {
          let scaledMesh = prediction.scaledMesh;
          return scaledMesh.map((point: number[]) => ([-point[0], -point[1], -point[2]]));
        });
        // console.log(pointsData);


        let flattenedPointsData: any = [];
        for (let i = 0; i < pointsData.length; i++) {
          flattenedPointsData = flattenedPointsData.concat(pointsData[i]);
        }

        // console.log(flattenedPointsData);

        const dataset = new ScatterGL.Dataset(flattenedPointsData);

        if (!scatterGLHasInitialized) {
          scatterGL.render(dataset);
        } else {
          scatterGL.updateDataset(dataset);
        }
        scatterGLHasInitialized = true;
      }
      // ..............................................................................
    }
  }
  //  stats.end();
  requestAnimationFrame(() => renderPrediction(model, ctx, ctxOut, video, scatterGL, img, imgHairBand, imgSunglass, renderMode));
};


const getAngleBetween = (x0: number, y0: number, x1: number, y1: number) => {
  return Math.atan2(x1 - x0, y1 - y0);
}