
import { NFaceCam } from './face'

import '@tensorflow/tfjs-backend-webgl';


export class Solution {
    public divHost: HTMLElement;
    constructor(id: string) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        const container = document.createElement('div');
        this.divHost.appendChild(container);
        container.id = 'container-video'
        container.style.alignItems = 'center';
        container.style.margin = '10%';
        // container.style.marginTop = '80px';
        // container.style.marginLeft = 'auto';
        // container.style.marginRight = 'auto';
        container.style.width = '50%';
        container.style.height = '600px';

        new NFaceCam(container.id);

    }
    public destroy() {
        try {
            while (this.divHost && this.divHost.lastElementChild) {
                const lastChild = this.divHost.lastElementChild as Node;
                this.divHost.removeChild(lastChild);
            }
        } catch (error) { }
    }
}
